#' Get Plot Sample IDs
#'
#' @description Get the sample IDs from a prepared plot. Useful if renaming in
#'   the plot legend.
#'
#'   Obtenez les ID d’échantillon à partir d’un tracé préparé. Utile si vous
#'   renommez dans la légende de le tracé
#'
#' @param ftir_spectra_plot A plot generated by [plot_ftir()] or
#'   [plot_ftir_stacked()].
#'
#'   Un tracé généré par [plot_ftir()] ou [plot_ftir_stacked()].
#'
#' @return A vector of factors corresponding to the sample IDs in the plot.
#'
#'   unvecteur de facteurs correspondant aux ID d'échantillon dans le tracé
#' @export
#'
#' @seealso [rename_plot_sample_ids()]
#' @examples
#' if (requireNamespace("ggplot2", quietly = TRUE)) {
#'   # Prepare a plot
#'   p <- plot_ftir(biodiesel)
#'
#'   # Get the Sample IDs
#'   get_plot_sample_ids <- (p)
#' }
get_plot_sample_ids <- function(ftir_spectra_plot) {
  # Package Checks
  if (!requireNamespace("ggplot2", quietly = TRUE)) {
    .pkg_abort(
      list(
        en = c(
          "{.pkg PlotFTIR} requires {.pkg ggplot2} package installation.",
          i = "Install {.pkg ggplot2} with {.run install.packages('ggplot2')}"
        ),
        fr = c(
          "{.pkg PlotFTIR} n\u00e9cessite l'installation du paquet {.pkg ggplot2}.",
          i = "Installez le paquet {.pkg ggplot2} avec la commande {.run install.packages('ggplot2')}"
        )
      ),
      call = rlang::caller_env(),
    )
  }
  if (!ggplot2::is_ggplot(ftir_spectra_plot)) {
    .pkg_abort(
      list(
        en = cli::format_inline(
          "Error in {.fn PlotFTIR::get_plot_sample_ids}. {.arg ftir_spectra_plot} must be a ggplot object. You provided {.obj_type_friendly {ftir_spectra_plot}}."
        ),
        fr = cli::format_inline(
          "Erreur dans {.fn PlotFTIR::get_plot_sample_ids}. {.arg ftir_spectra_plot} doit \u00eatre un objet ggplot. Vous avez fourni {.obj_type_friendly {ftir_spectra_plot}}."
        )
      )
    )
  }
  return(as.factor(unique(ftir_spectra_plot$data$sample_id)))
}

#' @title Check FTIR Data
#'
#' @description Check the provided FTIR data.frame is appropriate for
#'   manipulation or plotting. Not typically called directly, but as a function
#'   in data integrity check process before further calculation or plotting
#'   happens. Sets data.frame attribute `intensity` to `transmittance` or
#'   `absorbance` if not previously set.
#'
#'   Vérifie que le data.frame IRTF fourni est approprié pour la manipulation ou
#'   le tracé. Cette fonction n'est généralement pas appelée directement, mais
#'   elle est utilisée dans le cadre du processus de vérification de l'intégrité
#'   des données avant tout autre calcul ou tracé. Définit l'attribut data.frame
#'   `intensity` à `transmittance` ou `absorbance` s'il n'a pas été défini
#'   auparavant.
#'
#' @param ftir A data.frame of FTIR spectral data.
#'
#'   Un data.frame de données spectrales IRTF.
#'
#' @return Invisibly returns FTIR data if ok, or raises an error.
#'
#'   Renvoie de manière invisible les données IRTF si elles sont correctes, ou
#'   soulève une erreur.
#'
#' @export
#' @examples
#' # This returns (invisibly) the biodiesel data. If instead there was an issue
#' # with the data structure it would raise an error.
#' check_ftir_data(biodiesel)
check_ftir_data <- function(ftir) {
  fn <- try(deparse(sys.calls()[[sys.nframe() - 1]]), silent = TRUE)
  if (inherits(fn, 'try-error')) {
    fn <- "PlotFTIR::check_ftir_data"
  } else {
    fn <- paste0("PlotFTIR::", strsplit(fn, "(", fixed = TRUE)[[1]][1])
  }

  if ("ir" %in% class(ftir)) {
    .pkg_inform(
      list(
        en = "Converting {.pkg ir} data to {.pkg PlotFTIR} structure.",
        fr = "Conversion des donn\u00e9es {.pkg ir} en structure {.pkg PlotFTIR}."
      )
    )
    ftir <- ir_to_plotftir(ftir)
  }

  if ("Spectra" %in% class(ftir)) {
    .pkg_inform(
      list(
        en = "Converting {.pkg ChemoSpec} data to {.pkg PlotFTIR} structure.",
        fr = "Conversion des donn\u00e9es {.pkg ChemoSpec} en structure {.pkg PlotFTIR}."
      )
    )
    ftir <- chemospec_to_plotftir(ftir)
  }

  if (!(is.data.frame(ftir))) {
    .pkg_abort(
      list(
        en = cli::format_inline(
          "Error in {.fn {fn}}. {.arg ftir} must be a data frame. You provided {.obj_type_friendly ftir}."
        ),
        fr = cli::format_inline(
          "Erreur dans {.fn {fn}}. {.arg ftir} doit \u00eatre un data.frame. Vous avez fourni {.obj_type_friendly ftir}."
        )
      )
    )
  }
  if (!("sample_id" %in% colnames(ftir))) {
    .pkg_abort(
      list(
        en = cli::format_inline(
          "Error in {.fn {fn}}. {.arg ftir} is missing a column. It must contain a column named {.var sample_id}."
        ),
        fr = cli::format_inline(
          "Erreur dans {.fn {fn}}. {.arg ftir} ne contient pas une colonne. Il doit contenir une colonne nomm\u00e9e {.var sample_id}."
        )
      ),
      call = rlang::caller_env(),
    )
  }
  if (!("wavenumber" %in% colnames(ftir))) {
    .pkg_abort(
      list(
        en = cli::format_inline(
          "Error in {.fn {fn}}. {.arg ftir} is missing a column. It must contain a column named {.var wavenumber}."
        ),
        fr = cli::format_inline(
          "Erreur dans {.fn {fn}}. {.arg ftir} ne contient pas une colonne. Il doit contenir une colonne nomm\u00e9e {.var wavenumber}."
        )
      ),
      call = rlang::caller_env(),
    )
  }
  if (!any(colnames(ftir) == "absorbance", colnames(ftir) == "transmittance")) {
    .pkg_abort(
      list(
        en = cli::format_inline(
          "Error in {.fn {fn}}. {.arg ftir} must have one of {.var absorbance} or {.var transmittance} columns."
        ),
        fr = cli::format_inline(
          "Erreur dans {.fn {fn}}. {.arg ftir} doit avoir une des colonnes {.var absorbance} ou {.var transmittance}."
        )
      )
    )
  }
  if ("absorbance" %in% colnames(ftir) && "transmittance" %in% colnames(ftir)) {
    .pkg_abort(
      list(
        en = cli::format_inline(
          "Error in {.fn {fn}}. {.arg ftir} cannot contain both {.var absorbance} and {.var transmittance} columns."
        ),
        fr = cli::format_inline(
          "Erreur dans {.fn {fn}}. {.arg ftir} ne peut pas contenir les deux colonnes {.var absorbance} et {.var transmittance}."
        )
      )
    )
  }
  if (
    any(
      !(colnames(ftir) %in%
        c("sample_id", "wavenumber", "absorbance", "transmittance"))
    )
  ) {
    .pkg_abort(
      list(
        en = cli::format_inline(
          "Error in {.fn {fn}}. {.arg ftir} may only contain columns {.var sample_id}, {.var wavenumber}, and one of {.var absorbance} or {.var transmittance}."
        ),
        fr = cli::format_inline(
          "Erreur dans {.fn {fn}}. {.arg ftir} ne peut contenir que les colonnes {.var sample_id}, {.var wavenumber}, et une des colonnes {.var absorbance} ou {.var transmittance}."
        )
      )
    )
  }
  if (
    !is.null(attr(ftir, "intensity")) &&
      !(attr(ftir, "intensity") %in%
        c(
          "absorbance",
          "transmittance",
          "normalized absorbance",
          "normalized transmittance"
        ))
  ) {
    .pkg_abort(
      list(
        en = cli::format_inline(
          "Error in {.fn {fn}}. {.arg ftir} has unexpected attributes."
        ),
        fr = cli::format_inline(
          "Erreur dans {.fn {fn}}. {.arg ftir} a des attributs inattendus."
        )
      )
    )
  }

  if (is.null(attr(ftir, "intensity"))) {
    attr(ftir, "intensity") <- intensity_type(ftir)
  }

  class(ftir) <- unique(c("PlotFTIR_data", class(ftir)))

  invisible(ftir)
}


#' Print PlotFTIR Data
#'
#' @description
#' Pretty print method for PlotFTIR data structures, showing spectral range,
#' inferred resolution, intensity type, number of samples, and sample IDs.
#'
#' Méthode d'impression jolie pour les structures de données PlotFTIR, montrant
#' la plage spectrale, la résolution inférée, le type d'intensité, le nombre
#' d'échantillons et les ID d'échantillons.
#'
#' @param x A PlotFTIR data object.
#'
#'   Un objet de données PlotFTIR.
#'
#' @param ... Additional arguments passed to print.
#'
#'   Arguments supplémentaires passés à print.
#'
#' @return Invisibly returns the object.
#'
#'   Renvoie l'objet de manière invisible.
#'
#' @export
#' @method print PlotFTIR_data
print.PlotFTIR_data <- function(x, ...) {
  # Calculate all values first to avoid repetition
  wn <- sort(unique(x$wavenumber))
  res <- diff(wn)
  samples <- unique(x$sample_id)

  lang <- .get_language()

  if (lang == "fr") {
    cat("Donn\u00e9es PlotFTIR:\n")
    cat("  Plage spectrale:", min(wn), "-", max(wn), "cm\u207b\u00b9\\n")
    if (length(res) == 0) {
      cat("  R\u00e9solution: aucune\n")
    } else if (length(unique(res)) == 1) {
      cat("  R\u00e9solution:", unique(res), "cm\u207b\u00b9\\n")
    } else {
      cat("  R\u00e9solution: variable\n")
    }
    cat("  Type d'intensit\u00e9:", attr(x, "intensity"), "\n")
    cat("  Nombre d'\u00e9chantillons:", length(samples), "\n")
    if (length(samples) <= 5) {
      cat("  ID des \u00e9chantillon:", paste(samples, collapse = ", "), "\n")
    } else {
      cat(
        "  ID des \u00e9chantillons:",
        paste(utils::head(samples, 5), collapse = ", "),
        "...\n"
      )
    }
  } else {
    # English by default
    cat("PlotFTIR data:\n")
    cat("  Spectral range:", min(wn), "-", max(wn), "cm\u207b\u00b9\\n")
    if (length(res) == 0) {
      cat("  Resolution: none\n")
    } else if (length(unique(res)) == 1) {
      cat("  Resolution:", unique(res), "cm\u207b\u00b9\\n")
    } else {
      cat("  Resolution: variable\n")
    }
    cat("  Intensity type:", attr(x, "intensity"), "\n")
    cat("  Number of samples:", length(samples), "\n")
    if (length(samples) <= 5) {
      cat("  Sample IDs:", paste(samples, collapse = ", "), "\n")
    } else {
      cat(
        "  Sample IDs:",
        paste(utils::head(samples, 5), collapse = ", "),
        "...\n"
      )
    }
  }
  invisible(x)
}


#' Intensity Type
#'
#' @description Determines if the provided data has intensity type of absorbance
#'   or transmittance.
#'
#' @inheritParams conversion
#'
#' @return a character value 'absorbance' or 'transmittance'
#' @keywords internal
intensity_type <- function(ftir) {
  # Don't check_ftir_data to avoid a loop if called by check_ftir_data()

  if ("absorbance" %in% colnames(ftir)) {
    return("absorbance")
  } else if ("transmittance" %in% colnames(ftir)) {
    return("transmittance")
  }

  # implied else
  ftir <- ftir[, -which(names(ftir) %in% c("wavenumber", "sample_id"))]
  return(ifelse(max(ftir, na.rm = TRUE) > 10, "transmittance", "absorbance"))
}
